  const d = item.json;
  if (d.quantity === 0) outOfStock.push(d);
  else if (d.quantity <= (d.low_stock_threshold || 5)) lowStock.push(d);
  else healthy.push(d);
}

return [{ json: { lowStock, outOfStock, healthy, checked_at: new Date().toISOString() } }];

