const p = $input.first().json;
const cost = parseFloat(p.cost_price || 0);
const shipping = parseFloat(p.shipping_cost || 0);
const marketing = parseFloat(p.marketing_cost || cost * 0.1);
const marginPct = parseFloat(p.target_margin_pct || 30);

const basePrice = cost + shipping + marketing;
const sellingPrice = basePrice / (1 - marginPct / 100);
const discountedPrice = sellingPrice * 0.9;

return [{
  json: {
    product_id: p._id,
    product_name: p.title,
    cost_price: cost,
    shipping_cost: shipping,
    marketing_cost: marketing,
    selling_price: Math.round(sellingPrice * 100) / 100,
    discounted_price: Math.round(discountedPrice * 100) / 100,
    profit_margin_pct: marginPct,
    profit_amount: Math.round((sellingPrice - basePrice) * 100) / 100,
    calculated_at: new Date().toISOString()
  }
}];

