const newOrder = $('MongoDB Watch New Orders').first().json;
const history = $input.all().map(i=>i.json);
let riskScore = 0;
const flags = [];

if (parseFloat(newOrder.total_amount) > 500) { riskScore += 20; flags.push('High value order'); }
if (history.filter(o=>o.status==='refunded').length > 2) { riskScore += 30; flags.push('Multiple past refunds'); }
const recentOrders = history.filter(o=>Date.now()-new Date(o.created_at).getTime() < 3600000);
if (recentOrders.length > 3) { riskScore += 40; flags.push('Multiple orders in 1 hour'); }
if (history.length > 0 && history[0].shipping_address !== newOrder.shipping_address) { riskScore += 10; flags.push('New shipping address'); }
const duplicates = history.filter(o=>JSON.stringify(o.items)===JSON.stringify(newOrder.items) && o._id !== newOrder._id);
if (duplicates.length > 0) { riskScore += 35; flags.push('Duplicate order detected'); }

const risk_level = riskScore >= 60 ? 'high' : riskScore >= 30 ? 'medium' : 'low';
return [{ json: { order_id: newOrder._id, customer_email: newOrder.customer_email, risk_score: riskScore, risk_level, flags, order_amount: newOrder.total_amount } }];

