const orders = $('Get Daily Orders').all().map(i=>i.json);
const expenses = $('Get Daily Expenses').all().map(i=>i.json);

const revenue = orders.filter(o=>o.status!=='refunded').reduce((s,o)=>s+(parseFloat(o.total_amount)||0),0);
const refunds = orders.filter(o=>o.status==='refunded').reduce((s,o)=>s+(parseFloat(o.total_amount)||0),0);
const totalExpenses = expenses.reduce((s,e)=>s+(parseFloat(e.amount)||0),0);
const cogs = orders.reduce((s,o)=>s+(parseFloat(o.cost_of_goods)||0),0);
const grossProfit = revenue - cogs - refunds;
const netProfit = grossProfit - totalExpenses;
const profitMargin = revenue > 0 ? (netProfit/revenue*100) : 0;

return [{ json: { date: new Date().toISOString().slice(0,10), revenue: Math.round(revenue*100)/100, refunds: Math.round(refunds*100)/100, cogs: Math.round(cogs*100)/100, gross_profit: Math.round(grossProfit*100)/100, total_expenses: Math.round(totalExpenses*100)/100, net_profit: Math.round(netProfit*100)/100, profit_margin_pct: Math.round(profitMargin*10)/10, order_count: orders.length } }];

