const p = $input.first().json;
const checks = [];
let passed = true;

if (!p.title || p.title.length < 10) { checks.push({ check: 'title', status: 'fail', reason: 'Missing or too short title' }); passed = false; }
else checks.push({ check: 'title', status: 'pass' });

if (!p.description || p.description.length < 50) { checks.push({ check: 'description', status: 'fail', reason: 'Missing or too short description' }); passed = false; }
else checks.push({ check: 'description', status: 'pass' });

if (!p.selling_price || parseFloat(p.selling_price) <= 0) { checks.push({ check: 'price', status: 'fail', reason: 'Invalid or missing price' }); passed = false; }
else if (p.cost_price && parseFloat(p.selling_price) < parseFloat(p.cost_price)) { checks.push({ check: 'price', status: 'fail', reason: 'Selling price below cost' }); passed = false; }
else checks.push({ check: 'price', status: 'pass' });

if (!p.images || p.images.length === 0) { checks.push({ check: 'images', status: 'fail', reason: 'No product images' }); passed = false; }
else checks.push({ check: 'images', status: 'pass' });

if (!p.category) { checks.push({ check: 'category', status: 'warn', reason: 'No category assigned' }); }
else checks.push({ check: 'category', status: 'pass' });

if (!p.seo_keywords || p.seo_keywords.length === 0) { checks.push({ check: 'seo', status: 'warn', reason: 'No SEO keywords' }); }
else checks.push({ check: 'seo', status: 'pass' });

return [{ json: { product_id: p._id, product_title: p.title, checks, passed, checked_at: new Date().toISOString() } }];

